update QnA 
set qna_title = #{qnaTitle}, qna_content = #{qnaContent}, qna_lock = #{qnaLock}, qna_modified_time = sysdate 
where qna_post_id = #{qnaPostId}

mapper.select:
select * from ( SELECT qna_post_id, qna_title, qna_content, qna_user_id, qna_modified_time, qna_view_cnt, ROW_NUMBER() OVER (ORDER BY qna_post_id DESC) AS rnum FROM QNA
upper(qna_title) like upper(#{searchKeyword})
upper(qna_content) like upper(#{searchKeyword})
upper(qna_title) like upper(#{searchKeyword}) or upper(qna_content) like upper(#{searchKeyword})
upper(qna_user_id) like upper(#{searchKeyword})
) WHERE rnum BETWEEN #{pager.startRow} AND #{pager.lastRow}

SELECT qna_post_id, qna_title, qna_content, qna_user_id, qna_modified_time, qna_view_cnt, qna_lock, qna_state
FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY qna_post_id DESC) AS rnum, qna.*
    FROM QnA qna
)
WHERE rnum BETWEEN #{startRow} AND #{lastRow}
